arguments.command:
cd /workspace && python3 - <<'EOF'
import json
rows = [json.loads(l) for l in open('observed_run/wandb-history.jsonl')]
cols = ["training/global_step","critic/score/mean","critic/rewards/mean","actor/pg_loss","actor/kl_loss","actor/grad_norm","actor/entropy","actor/ppo_kl","actor/pg_clipfrac","response_length/mean","response_length/clip_ratio","response/aborted_ratio","val-core/openai/gsm8k/acc/mean@1","timing_s/step","rollout_corr/kl","training/rollout_probs_diff_mean","actor/lr"]
hdr = ["step","score","rew","pg_loss","kl_loss","gnorm","ent","ppo_kl","clipf","rlen","rclip","abort","VAL","t_step","rc_kl","rpd","lr"]
print("\t".join(hdr))
for r in rows:
    vals=[]
    for c in cols:
        v = r.get(c)
        if v is None: vals.append("-")
        elif isinstance(v,float): vals.append(f"{v:.4g}")
        else: vals.append(str(v))
    print("\t".join(vals))
EOF

